using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Diagnostics;
namespace GpuPro.Windows;
public sealed partial class MainWindow {
 void BuildDependencyControls(){body.Children.Add(Section("Dependências do aplicativo",Text("As bibliotecas da interface e dos testes acompanham o aplicativo. Driver e runtime gráfico vêm do fabricante. FFmpeg e runtime Visual C++ podem ser instalados pelo winget."),Button("Instalar dependências · winget",async()=>await InstallWindowsDependencies())));}
 static string? FindTool(string name){var folders=(Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator).Concat(new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","WinGet","Links"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","WindowsApps")});return folders.Select(p=>Path.Combine(p,name)).FirstOrDefault(File.Exists);}
 async Task InstallWindowsDependencies(){try{if(worker!=null||benchmark)throw new InvalidOperationException("Encerre o teste antes de instalar dependências.");string winget=FindTool("winget.exe")??throw new IOException("winget não encontrado. Instale ou atualize o Instalador de Aplicativos da Microsoft Store.");var ffmpeg=new CheckBox{Content="FFmpeg · testes de encoder e decoder",IsChecked=FindTool("ffmpeg.exe")==null};var runtime=new CheckBox{Content="Microsoft Visual C++ Runtime x64",IsChecked=!File.Exists(Path.Combine(Environment.SystemDirectory,"vcruntime140.dll"))||!File.Exists(Path.Combine(Environment.SystemDirectory,"msvcp140.dll"))};var stack=new StackPanel{Spacing=12};stack.Children.Add(Text("Escolha as dependências. O winget mostrará a origem, os termos e o instalador. Drivers NVIDIA, AMD e Intel não são substituídos por esta ação."));stack.Children.Add(ffmpeg);stack.Children.Add(runtime);var dialog=new ContentDialog{XamlRoot=Root.XamlRoot,Title="Instalar dependências",Content=stack,PrimaryButtonText="Continuar com winget",CloseButtonText="Cancelar",DefaultButton=ContentDialogButton.Close};if(await dialog.ShowAsync()!=ContentDialogResult.Primary)return;var packages=new List<string>();if(ffmpeg.IsChecked==true)packages.Add("Gyan.FFmpeg");if(runtime.IsChecked==true)packages.Add("Microsoft.VCRedist.2015+.x64");foreach(var package in packages){using var process=Process.Start(new ProcessStartInfo(winget,"install --id "+package+" --exact --source winget --interactive"){UseShellExecute=true})??throw new IOException("winget não iniciou.");await process.WaitForExitAsync();Record("winget "+package+": "+process.ExitCode);if(process.ExitCode!=0)throw new IOException("winget não confirmou "+package+". Confira a mensagem do instalador.");}var executable=FindTool("ffmpeg.exe");if(executable!=null){Directory.CreateDirectory(dataRoot);File.WriteAllText(Path.Combine(dataRoot,"ffmpeg-path.txt"),Path.GetDirectoryName(executable));}Record(packages.Count==0?"Nenhuma dependência selecionada.":"Instalação concluída. Reabra o aplicativo para atualizar os caminhos do sistema.");}catch(Exception e){TestError(e);}}
}
